import {initial,presets,HORIZON,EPISODES} from './engine.mjs';
import {drawRoom,drawCurve} from './draw.mjs';
const $=id=>document.getElementById(id);
const tasks={
 pickup:{title:'把垃圾丢进垃圾桶',mission:'目标很简单：垃圾真正入桶。你给的奖励，会让它怎么做？',metric:'垃圾是否入桶',fields:[['pick','每次捡起垃圾',0,5,.5,'重复捡同一件垃圾，也能再次拿到奖励。'],['finish','垃圾真正入桶',0,20,1,'只有丢进垃圾桶才得到这笔奖励。'],['cost','每走一步的成本',.02,1,.02,'每个动作都会扣分，包括捡起、放下和等待。']]},
 delivery:{title:'送到包裹，也别撞坏花盆',mission:'目标：送达包裹，保留完好的花盆。直线最近，绕路更安全。',metric:'花盆是否完好',fields:[['finish','包裹送达',0,20,1,'送到右侧收件处，任务立即结束。'],['damage','撞碎花盆的罚分',0,15,1,'花盆第一次被撞碎时扣分。'],['cost','每走一步的成本',.1,1,.1,'赶时间的压力：绕路也要付出步数成本。']]},
 hide:{title:'让房间真的干净起来',mission:'目标：垃圾进入垃圾桶。藏在地毯下面，不算真正清理。',metric:'垃圾是否入桶',fields:[['hide','藏到地毯下',0,15,1,'表面变干净了。任务会结束，但垃圾还在房间里。'],['finish','垃圾真正入桶',0,20,1,'用真实处理结果代替“看起来干净”。'],['cost','每走一步的成本',.02,1,.02,'同样的奖励，它可能更愿意选近的地方。']]}
};
let task='pickup',rewards={...presets.pickup.bad},worker=null,generation=0,result=null,trained=null,playing=false,frameIndex=0,elapsed=0,lastTime=0,url=null;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function setStatus(s){$('status').textContent=s;}
function controls(){for(const id of ['play','replay','skip','card','json'])$(id).disabled=!result;$('play').textContent=playing?'暂停 Ⅱ':'播放 ▷';$('play').setAttribute('aria-label',playing?'暂停播放':'播放策略');}
function stop(){generation++;worker?.terminate();worker=null;$('cancel').hidden=true;$('train').disabled=false;}
function invalidate(){stop();result=null;trained=null;playing=false;frameIndex=0;elapsed=0;controls();$('progress').value=0;$('episodes').textContent='0 局';drawCurve($('curve'),[]);setStatus('规则已修改。重新训练后，才会产生新的行为。');$('stage-badge').textContent='待重新训练';$('verdict').textContent='奖励变了，旧策略已收起。按下“重新训练”，看看它会学成什么样。';$('current-outcome').textContent='等待重新训练';$('current-stats').textContent='当前规则尚未评估';drawFrame({state:initial(task),reward:0,total:0,event:'等待上班'});}
function fields(){const box=$('sliders');box.replaceChildren();for(const [key,label,min,max,step,note]of tasks[task].fields){const row=document.createElement('div');row.className='slider-row';const heading=document.createElement('div');heading.className='slider-label';const lab=document.createElement('label');lab.htmlFor='r-'+key;lab.textContent=label;const out=document.createElement('output');out.htmlFor=lab.htmlFor;out.textContent=(key==='cost'||key==='damage'?'−':'+')+rewards[key];const input=document.createElement('input');input.type='range';input.id=lab.htmlFor;input.min=min;input.max=max;input.step=step;input.value=rewards[key];const small=document.createElement('small');small.textContent=note;heading.append(lab,out);row.append(heading,input,small);box.append(row);input.oninput=()=>{rewards[key]=Number(input.value);out.textContent=(key==='cost'||key==='damage'?'−':'+')+input.value;invalidate();markPreset();};}}
function markPreset(){for(const [id,p]of [['bad','bad'],['good','good']]){const on=Object.keys(rewards).every(k=>rewards[k]===presets[task][p][k]);$(id).classList.toggle('selected',on);$(id).setAttribute('aria-pressed',String(on));}}
function choose(id){stop();task=id;rewards={...presets[task].bad};for(const b of document.querySelectorAll('[data-task]'))b.setAttribute('aria-pressed',String(b.dataset.task===task));$('task-title').textContent=tasks[task].title;$('mission').textContent=tasks[task].mission;$('metric-label').textContent=tasks[task].metric;$('baseline-outcome').textContent='训练后显示';$('baseline-stats').textContent='等待真实策略评估';fields();markPreset();invalidate();start();}
function outcome(run){if(task==='delivery')return run.final.done?(run.final.broken?'送到了，花盆也碎了':'送达，而且花盆完好'):'还没有送到';if(run.final.item===-2)return '垃圾真的进桶了';if(run.final.item===-3)return '地面干净，垃圾藏在毯下';return run.picks>3?'反复捡放，垃圾没进桶':'垃圾还没有进桶';}
function stats(run){return `${run.frames.length-1} 步 · 奖励 ${run.total.toFixed(1)} 分${task==='delivery'?' · 花盆'+(run.final.broken?'损坏':'完好'):' · 捡起 '+run.picks+' 次'}`;}
function conclusion(run){if(task==='pickup'&&run.picks>3)return `它捡起了 ${run.picks} 次垃圾，却一次也没丢进桶。每次捡起都有奖励，反复捡放就能刷分。试着取消捡拾奖励，只奖励真正入桶。`;if(task==='delivery'&&run.final.broken)return '包裹送到了，花盆却碎了。规则奖励送达和节省步数，却没有足够惩罚破坏。试着提高碰撞罚分，再训练一次。';if(task==='hide'&&run.final.item===-3)return '地面看起来干净了，垃圾却藏在地毯下面。它拿到了“看不见垃圾”的奖励。试着只奖励真正入桶。';if(run.final.done&&run.final.item===-2)return '这一次，拿分和完成任务终于一致了。换一个训练种子，或继续调整奖励，看看结果是否稳定。';return '80 步结束，实际目标没有完成。这组奖励可能让它不愿行动或停留在循环里；增加完成奖励，再重新训练试试。';}
function start(){stop();result=null;trained={task,rewards:{...rewards},seed:Number($('seed').value)};playing=false;frameIndex=0;elapsed=0;controls();$('train').disabled=true;$('cancel').hidden=false;$('progress').value=0;$('stage-badge').textContent='正在本机学习';$('current-outcome').textContent='训练中…';$('current-stats').textContent='从零初始化 Q 表';$('verdict').textContent='机器人正在试错。动画将在训练完成后播放实际策略。';drawFrame({state:initial(task),reward:0,total:0,event:'学习中'});const token=generation;const begin=performance.now();setStatus('正在本机训练 6,000 局…');
 try{worker=new Worker(new URL('./worker.mjs',import.meta.url),{type:'module'});worker.onmessage=({data:m})=>{if(token!==generation)return;if(m.type==='progress'){$('progress').value=m.episode;$('episodes').textContent=m.episode.toLocaleString()+' 局';drawCurve($('curve'),m.curve);if(m.episode===EPISODES)setStatus('当前策略已学完，正在评估同种子的原始规则…');}else if(m.type==='done'){worker.terminate();worker=null;result=m;$('train').disabled=false;$('cancel').hidden=true;playing=!reduced;lastTime=performance.now();$('stage-badge').textContent='已学策略 / 关闭探索';setStatus(`本机训练完成 · ${((performance.now()-begin)/1000).toFixed(1)} 秒 · 种子 ${m.seed}`);$('baseline-outcome').textContent=outcome(m.baseline);$('baseline-stats').textContent=stats(m.baseline);$('current-outcome').textContent=outcome(m.run);$('current-stats').textContent=stats(m.run);$('verdict').textContent='训练完成。观看它的动作，或点击“看结局”查看实际结果。';controls();}else fail(m.message);};worker.onerror=()=>fail('训练线程启动失败，请刷新重试。');worker.postMessage(trained);}catch(e){fail(e.message);}}
function fail(message){stop();playing=false;result=null;controls();setStatus('训练失败：'+message);$('stage-badge').textContent='训练未完成';$('verdict').textContent='没有生成可播放的策略，请重新训练。';}
function drawFrame(f,prev,blend=1){drawRoom($('room'),task,f,prev,blend,result?.run.frames.slice(0,frameIndex+1)||[]);$('reward').textContent=f.total.toFixed(1);$('objective').textContent=task==='delivery'?(f.state.broken?'已损坏':'完好'):(f.state.item===-2?'已入桶':f.state.item===-3?'藏在毯下':'尚未入桶');$('event').textContent=f.event;$('step-count').textContent=`${frameIndex} / ${result?result.run.frames.length-1:HORIZON} 步`;}
function tick(now){const dt=Math.min(100,now-lastTime);lastTime=now;if(result){const frames=result.run.frames,duration=650/Number($('speed').value);if(playing){elapsed+=dt;while(elapsed>=duration&&frameIndex<frames.length-1){elapsed-=duration;frameIndex++;}if(frameIndex===frames.length-1){playing=false;elapsed=duration;$('verdict').textContent=conclusion(result.run);$('stage-badge').textContent='本轮结束';controls();}}const f=frames[frameIndex];drawFrame(f,frames[Math.max(0,frameIndex-1)],reduced?1:Math.min(1,elapsed/(duration*.7)));}requestAnimationFrame(tick);}
$('train').onclick=start;$('cancel').onclick=()=>{invalidate();setStatus('训练已取消。可以调整奖励后重试。');};$('seed').onchange=invalidate;
for(const b of document.querySelectorAll('[data-task]'))b.onclick=()=>choose(b.dataset.task);
for(const id of ['bad','good'])$(id).onclick=()=>{rewards={...presets[task][id]};fields();markPreset();invalidate();};
$('play').onclick=()=>{if(!result)return;if(frameIndex===result.run.frames.length-1){frameIndex=0;elapsed=0;}playing=!playing;controls();};$('replay').onclick=()=>{if(!result)return;frameIndex=0;elapsed=0;playing=true;$('stage-badge').textContent='重播实际策略';controls();};$('skip').onclick=()=>{if(!result)return;frameIndex=result.run.frames.length-1;elapsed=1000;playing=false;$('verdict').textContent=conclusion(result.run);$('stage-badge').textContent='本轮结束';controls();};
function exported(blob,name,preview){if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(blob);$('export-link').href=url;$('export-link').download=name;$('export-image').hidden=!preview;if(preview)$('export-image').src=url;else $('export-image').removeAttribute('src');$('export-note').textContent=preview?'成绩单展示本轮完整评估结果；动画画面为最终状态。':'包含奖励、随机种子、逐步状态、动作和得分；可用开源引擎复现。';$('export').showModal();}
$('close-export').onclick=()=>$('export').close();$('json').onclick=()=>{if(!result||!trained)return;exported(new Blob([JSON.stringify({schema:1,engine:'tabular-q-learning-v1',episodes:EPISODES,horizon:HORIZON,alpha:.18,gamma:.96,...trained,...result},null,2)],{type:'application/json'}),'reward-lab-run.json',false);};
$('card').onclick=()=>{if(!result||!trained)return;const c=document.createElement('canvas');c.width=1200;c.height=1100;const g=c.getContext('2d');g.fillStyle='#f5f3ed';g.fillRect(0,0,1200,1100);g.fillStyle='#dc452b';g.fillRect(60,52,18,18);g.fillStyle='#242622';g.font='bold 22px Arial';g.fillText('MISREAD LAB / 003',94,70);g.font='bold 44px Arial';g.fillText('老板，这就是你写的规则。',60,145);g.font='24px Arial';g.fillText(tasks[task].title+' · 种子 '+trained.seed,60,193);const scene=document.createElement('canvas');scene.width=840;scene.height=600;const fs=result.run.frames;drawRoom(scene,task,fs.at(-1),null,1,fs);g.drawImage(scene,60,230,1080,650);g.fillStyle='#dc452b';g.font='bold 33px Arial';g.fillText(outcome(result.run),60,939);g.fillStyle='#646d59';g.font='22px Arial';g.fillText(stats(result.run),60,982);g.font='18px Arial';g.fillText('真实本地 Q-learning · 教学环境 · jingsong-wang.github.io/reward-lab/',60,1050);c.toBlob(b=>{if(b)exported(b,'reward-lab-card.png',true);},'image/png');};
choose('pickup');requestAnimationFrame(tick);
